import type { DbSeedFn } from "wasp/server";
import { sanitizeAndSerializeProviderData } from "wasp/server/auth";

export const seedData: DbSeedFn = async (prisma) => {
  // Check if testuser already exists
  const existingUser = await prisma.user.findFirst({
    where: {
      auth: {
        identities: {
          some: {
            providerName: "username",
            providerUserId: "testuser",
          },
        },
      },
    },
  });

  let user;
  if (!existingUser) {
    user = await prisma.user.create({
      data: {
        auth: {
          create: {
            identities: {
              create: {
                providerName: "username",
                providerUserId: "testuser",
                providerData: await sanitizeAndSerializeProviderData<"username">({
                  hashedPassword: "password123",
                }),
              },
            },
          },
        },
      },
    });
  } else {
    user = existingUser;
  }

  // Clear existing transactions for this user so seeding is idempotent/exact
  await prisma.transaction.deleteMany({
    where: { userId: user.id },
  });

  // Seed exactly the 4 transactions
  const transactionsToSeed = [
    {
      date: new Date("2026-07-01T00:00:00.000Z"),
      amount: 5000.0,
      type: "INCOME",
      category: "Sales",
      description: "Project payment",
      userId: user.id,
    },
    {
      date: new Date("2026-07-15T00:00:00.000Z"),
      amount: 1200.0,
      type: "EXPENSE",
      category: "Marketing",
      description: "Ad campaign",
      userId: user.id,
    },
    {
      date: new Date("2026-07-20T00:00:00.000Z"),
      amount: 800.0,
      type: "EXPENSE",
      category: "Software",
      description: "SaaS subscriptions",
      userId: user.id,
    },
    {
      date: new Date("2026-07-25T00:00:00.000Z"),
      amount: 2500.0,
      type: "INCOME",
      category: "Investment",
      description: "Dividend payout",
      userId: user.id,
    },
  ];

  for (const tx of transactionsToSeed) {
    await prisma.transaction.create({
      data: tx,
    });
  }
};

import { HttpError } from "wasp/server";
import type { CreateTransaction } from "wasp/server/operations";

export const createTransaction: CreateTransaction<{
  date: string;
  amount: number;
  type: "INCOME" | "EXPENSE";
  category: string;
  description: string;
}, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const { date, amount, type, category, description } = args;

  return context.entities.Transaction.create({
    data: {
      date: new Date(date),
      amount,
      type,
      category,
      description,
      user: { connect: { id: context.user.id } },
    },
  });
};

import { HttpError } from "wasp/server";
import type { GetAnalytics } from "wasp/server/operations";

export const getAnalytics: GetAnalytics<{
  startDate: string;
  endDate: string;
  resolution: "day" | "week" | "month";
}, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const { startDate, endDate, resolution } = args;
  const userId = context.user.id;

  const start = new Date(startDate + "T00:00:00.000Z");
  const end = new Date(endDate + "T23:59:59.999Z");
  const startMillis = start.getTime();
  const endMillis = end.getTime();
  const startIso = start.toISOString();
  const endIso = end.toISOString();

  // 1. Time-series aggregation using Prisma raw query
  const rawRows: any[] = await context.entities.Transaction.$queryRaw`
    SELECT 
      CASE 
        WHEN typeof(date) = 'integer' OR typeof(date) = 'real' THEN
          CASE ${resolution}
            WHEN 'day' THEN strftime('%Y-%m-%d', date / 1000.0, 'unixepoch')
            WHEN 'month' THEN strftime('%Y-%m', date / 1000.0, 'unixepoch')
            WHEN 'week' THEN strftime('%Y-W%W', date / 1000.0, 'unixepoch')
          END
        ELSE
          CASE ${resolution}
            WHEN 'day' THEN strftime('%Y-%m-%d', date)
            WHEN 'month' THEN strftime('%Y-%m', date)
            WHEN 'week' THEN strftime('%Y-W%W', date)
          END
      END as aggDate,
      SUM(CASE WHEN type = 'INCOME' THEN amount ELSE 0 END) as income,
      SUM(CASE WHEN type = 'EXPENSE' THEN amount ELSE 0 END) as expense
    FROM "Transaction"
    WHERE userId = ${userId}
      AND (
        (typeof(date) = 'integer' AND date >= ${startMillis} AND date <= ${endMillis})
        OR
        (typeof(date) <> 'integer' AND date >= ${startIso} AND date <= ${endIso})
        OR
        (date >= ${start} AND date <= ${end})
      )
    GROUP BY aggDate
    ORDER BY aggDate ASC
  `;

  const timeSeries = rawRows.map((row: any) => {
    const income = Number(row.income || 0);
    const expense = Number(row.expense || 0);
    return {
      date: row.aggDate,
      income,
      expense,
      net: income - expense,
    };
  });

  // 2. Category breakdown using Prisma raw query
  const categoryRows: any[] = await context.entities.Transaction.$queryRaw`
    SELECT 
      category,
      SUM(amount) as amount,
      type
    FROM "Transaction"
    WHERE userId = ${userId}
      AND (
        (typeof(date) = 'integer' AND date >= ${startMillis} AND date <= ${endMillis})
        OR
        (typeof(date) <> 'integer' AND date >= ${startIso} AND date <= ${endIso})
        OR
        (date >= ${start} AND date <= ${end})
      )
    GROUP BY category, type
  `;

  const categoryBreakdown = categoryRows.map((row: any) => ({
    category: row.category,
    amount: Number(row.amount || 0),
    type: row.type as "INCOME" | "EXPENSE",
  }));

  // 3. Compute Summary
  const totalIncome = timeSeries.reduce((sum, item) => sum + item.income, 0);
  const totalExpense = timeSeries.reduce((sum, item) => sum + item.expense, 0);
  const netSavings = totalIncome - totalExpense;
  const savingsRate = totalIncome > 0 ? (netSavings / totalIncome) * 100 : 0;

  return {
    timeSeries,
    categoryBreakdown,
    summary: {
      totalIncome,
      totalExpense,
      netSavings,
      savingsRate,
    },
  };
};

import { useState } from "react";
import type { AuthUser } from "wasp/auth";
import { logout } from "wasp/client/auth";
import { useQuery, getAnalytics, createTransaction } from "wasp/client/operations";

export const MainPage = ({ user }: { user: AuthUser }) => {
  const [startDate, setStartDate] = useState("2026-07-01");
  const [endDate, setEndDate] = useState("2026-07-31");
  const [resolution, setResolution] = useState<"day" | "week" | "month">("day");

  // Form state for creating a transaction
  const [newDate, setNewDate] = useState("2026-07-01");
  const [newAmount, setNewAmount] = useState("");
  const [newType, setNewType] = useState<"INCOME" | "EXPENSE">("INCOME");
  const [newCategory, setNewCategory] = useState("");
  const [newDescription, setNewDescription] = useState("");
  const [formError, setFormError] = useState("");

  const { data: analyticsData, isLoading, error } = useQuery(getAnalytics, {
    startDate,
    endDate,
    resolution,
  });

  const handleCreateTransaction = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError("");

    if (!newDate || !newAmount || !newCategory || !newDescription) {
      setFormError("All fields are required.");
      return;
    }

    const amountNum = parseFloat(newAmount);
    if (isNaN(amountNum) || amountNum <= 0) {
      setFormError("Amount must be a positive number.");
      return;
    }

    try {
      await createTransaction({
        date: newDate,
        amount: amountNum,
        type: newType,
        category: newCategory,
        description: newDescription,
      });

      // Reset form
      setNewAmount("");
      setNewCategory("");
      setNewDescription("");
    } catch (err: any) {
      setFormError(err.message || "Failed to create transaction.");
    }
  };

  const handleExportCSV = () => {
    if (!analyticsData || !analyticsData.timeSeries) return;

    // Filter timeSeries to only include rows with non-zero activity (income or expense > 0)
    const filteredRows = analyticsData.timeSeries.filter(
      (row: any) => row.income !== 0 || row.expense !== 0
    );

    // Generate CSV content
    const headers = "Date,Income,Expense,Net";
    const csvLines = filteredRows.map(
      (row: any) => `${row.date},${row.income},${row.expense},${row.net}`
    );
    const csvContent = [headers, ...csvLines].join("\n");

    // Create downloadable blob
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "analytics_export.csv");
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const summary = analyticsData?.summary || {
    totalIncome: 0,
    totalExpense: 0,
    netSavings: 0,
    savingsRate: 0,
  };

  const timeSeries = analyticsData?.timeSeries || [];
  const categoryBreakdown = analyticsData?.categoryBreakdown || [];

  return (
    <div style={{ fontFamily: "sans-serif", padding: "2rem", maxWidth: "1200px", margin: "0 auto" }}>
      <header style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: "1px solid #ccc", paddingBottom: "1rem", marginBottom: "2rem" }}>
        <div>
          <h1 style={{ margin: 0 }}>Financial Analytics Dashboard</h1>
          <p style={{ margin: "0.5rem 0 0 0", color: "#666" }}>Logged in as {user.getFirstProviderUserId()}</p>
        </div>
        <button 
          onClick={logout} 
          style={{ padding: "0.5rem 1rem", backgroundColor: "#f44336", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Logout
        </button>
      </header>

      {/* Controls */}
      <section style={{ display: "flex", gap: "1.5rem", flexWrap: "wrap", backgroundColor: "#f9f9f9", padding: "1.5rem", borderRadius: "8px", marginBottom: "2rem" }}>
        <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
          <label htmlFor="start-date" style={{ fontWeight: "bold" }}>Start Date</label>
          <input 
            type="date" 
            id="start-date" 
            data-testid="start-date" 
            value={startDate} 
            onChange={(e) => setStartDate(e.target.value)}
            style={{ padding: "0.5rem", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
          <label htmlFor="end-date" style={{ fontWeight: "bold" }}>End Date</label>
          <input 
            type="date" 
            id="end-date" 
            data-testid="end-date" 
            value={endDate} 
            onChange={(e) => setEndDate(e.target.value)}
            style={{ padding: "0.5rem", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
          <label htmlFor="resolution" style={{ fontWeight: "bold" }}>Resolution</label>
